import{_ as s,o as a,c as t,a5 as e}from"./chunks/framework.BEZBAInb.js";const g=JSON.parse('{"title":"語法高亮器","description":"","frontmatter":{"title":"語法高亮器","order":5},"headers":[],"relativePath":"tc/2.4/tutorial/core/ks-editor-highlighter.md","filePath":"tc/2.4/tutorial/core/ks-editor-highlighter.md","lastUpdated":1788455378000}'),h={name:"tc/2.4/tutorial/core/ks-editor-highlighter.md"};function l(n,i,p,r,d,o){return a(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="knd-kshighlighter-編輯器語法高亮" tabindex="-1">KND_KsHighlighter 編輯器語法高亮 <a class="header-anchor" href="#knd-kshighlighter-編輯器語法高亮" aria-label="Permalink to &quot;KND_KsHighlighter 編輯器語法高亮&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>語法高亮是編輯器的重要組成部分，能幫助開發者直觀識別程式碼結構，從而提升編寫效率與可讀性。<br><code>KND_KsHighlighter</code> 是基於 Godot 引擎 <code>SyntaxHighlighter</code> 實作的高亮器，專門用於 KS 腳本。它將高亮規則集中定義在單一腳本中，使自訂與擴充變得非常靈活——你可以輕鬆調整現有規則，也可以加入全新的配色方案。</p><h2 id="基本實作" tabindex="-1">基本實作 <a class="header-anchor" href="#基本實作" aria-label="Permalink to &quot;基本實作&quot;">​</a></h2><p>在 <code>KND_KsHighlighter</code> 中，高亮規則儲存為一個陣列，每個陣列元素都是一個字典，包含兩個鍵：</p><ul><li><code>regex</code>：用於匹配文字的正規表示式（Godot 的 RegEx 語法）。</li><li><code>color</code>：匹配文字的顏色，使用 <code>Color(r, g, b, a)</code> 表示，其中 <code>a</code> 為透明度（可選，預設為 1.0）。</li></ul><p>範例結構如下：</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	&quot;regex&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">b(if|else|endif)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	&quot;color&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>高亮器會依照陣列順序依次匹配，後套用的規則可能覆蓋先前的匹配，因此規則順序至關重要（建議將通用命令放在前面，字串和註解放在後面，以確保覆蓋效果合理）。</p><h2 id="自訂配色方案" tabindex="-1">自訂配色方案 <a class="header-anchor" href="#自訂配色方案" aria-label="Permalink to &quot;自訂配色方案&quot;">​</a></h2><p>你可以透過兩種方式為編輯器套用自訂高亮：</p><h3 id="方式一-修改資源檔案-推薦" tabindex="-1">方式一：修改資源檔案（推薦） <a class="header-anchor" href="#方式一-修改資源檔案-推薦" aria-label="Permalink to &quot;方式一：修改資源檔案（推薦）&quot;">​</a></h3><p>預設配色方案以資源檔案形式儲存在：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>res://addons/konado/editor/ks_editor/ks_syntax_highlighter.tres</span></span></code></pre></div><p>直接編輯該資源檔案可以保留修改，並避免每次重新生成。<br> 在程式碼中載入並使用該資源：</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set_syntax_highlighter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">load</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;res://addons/konado/editor/ks_editor/ks_syntax_highlighter.tres&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><h3 id="方式二-動態建立實例" tabindex="-1">方式二：動態建立實例 <a class="header-anchor" href="#方式二-動態建立實例" aria-label="Permalink to &quot;方式二：動態建立實例&quot;">​</a></h3><p>你也可以在程式碼中直接建立新的 <code>KND_KsHighlighter</code> 實例，並為其設定自訂規則（例如透過修改腳本中的 <code>highlight_rules</code>）：</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set_syntax_highlighter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">KND_KsHighlighter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span></code></pre></div><blockquote><p><strong>注意</strong>：如果直接修改了 <code>KND_KsHighlighter.gd</code> 腳本，可能需要重新生成資源檔案才能使變更生效。推薦優先使用資源檔案方式，以便更清晰地管理配色。</p></blockquote>`,20)])])}const c=s(h,[["render",l]]);export{g as __pageData,c as default};
